package io.knowledgebrain.content;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.content.attachments.v1.*;
import com.google.protobuf.ByteString;
final class NoteAttachmentStore {
 record Attachment(UUID attachmentId,UUID mediaId,String filename,String mimeType,long byteSize,String sha256){}
 record Snapshot(UUID noteId,long attachmentVersion,List<Attachment> items){}
 record Revision(UUID revisionId,long attachmentVersion,UUID actorId,Instant occurredAt,Snapshot snapshot){}
 private final JdbcTemplate jdbc;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=new JsonMapper();
 NoteAttachmentStore(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;ids=new UuidV7(clock);}
 Snapshot get(NoteStore.Note note){long version=jdbc.queryForObject("SELECT attachment_version FROM note WHERE note_id=?",Long.class,note.noteId());var items=jdbc.query("SELECT attachment_id,media_id,filename,mime_type,byte_size,sha256 FROM note_attachment WHERE space_id=? AND note_id=? ORDER BY ordinal",(rs,n)->new Attachment(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getLong(5),rs.getString(6)),note.spaceId(),note.noteId());return new Snapshot(note.noteId(),version,List.copyOf(items));}
 Snapshot replace(NoteStore.Note note,UUID actor,long expected,List<MediaAvailabilityClient.File> files,String trace){var prior=get(note);if(prior.attachmentVersion()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Attachments changed; reload before saving");if(files.size()>20 || files.stream().map(MediaAvailabilityClient.File::mediaId).distinct().count()!=files.size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid attachments");var stable=new HashMap<UUID,UUID>();prior.items().forEach(x->stable.put(x.mediaId(),x.attachmentId()));jdbc.update("DELETE FROM note_attachment WHERE note_id=?",note.noteId());int ordinal=0;for(var file:files){NoteStore.id(file.mediaId());if(!note.spaceId().equals(file.spaceId()) || !"AVAILABLE".equals(file.state()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only available same-Space Media can be attached");UUID id=stable.containsKey(file.mediaId())?stable.get(file.mediaId()):ids.next();jdbc.update("INSERT INTO note_attachment(attachment_id,space_id,note_id,media_id,ordinal,filename,mime_type,byte_size,sha256) VALUES (?,?,?,?,?,?,?,?,?)",id,note.spaceId(),note.noteId(),file.mediaId(),ordinal++,file.filename(),file.mimeType(),file.byteSize(),file.sha256());}return publish(note,actor,trace);}
 void retire(NoteStore.Note note,UUID actor,String trace){if(get(note).attachmentVersion()==0)return;jdbc.update("DELETE FROM note_attachment WHERE note_id=?",note.noteId());publish(note,actor,trace);}
 private Snapshot publish(NoteStore.Note note,UUID actor,String trace){jdbc.update("UPDATE note SET attachment_version=attachment_version+1 WHERE note_id=?",note.noteId());var value=get(note);UUID revision=ids.next(),event=ids.next();Instant now=clock.instant();jdbc.update("INSERT INTO note_attachment_revision(revision_id,space_id,note_id,attachment_version,actor_id,occurred_at,snapshot) VALUES (?,?,?,?,?,?,?::jsonb)",revision,note.spaceId(),note.noteId(),value.attachmentVersion(),actor,Timestamp.from(now),json.writeValueAsString(value));var payload=NoteAttachmentsChangedPayloadV1.newBuilder().setNoteId(note.noteId().toString()).setAttachmentVersion(value.attachmentVersion()).setNoteVersion(note.version()).setNoteState(note.state()).setRevisionId(revision.toString());for(var item:value.items())payload.addAttachments(NoteAttachmentV1.newBuilder().setAttachmentId(item.attachmentId().toString()).setMediaId(item.mediaId().toString()).setFilename(item.filename()).setMimeType(item.mimeType()).setByteSize(item.byteSize()).setSha256(item.sha256()));var envelope=AttachmentEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType("NoteAttachmentsChanged").setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("content-service").setAggregateType("NoteAttachments").setAggregateId(note.noteId().toString()).setSpaceId(note.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(ByteString.copyFrom(payload.build().toByteArray())).build();jdbc.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'note-attachments',?,'NoteAttachmentsChanged',?,?,'content','note-attachments-events','1',?)",event,note.noteId(),Timestamp.from(now),trace,envelope.toByteArray());return value;}
 List<Revision> history(UUID note,long before,int limit){return jdbc.query("SELECT revision_id,attachment_version,actor_id,occurred_at,snapshot::text FROM note_attachment_revision WHERE note_id=? AND attachment_version<? ORDER BY attachment_version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant(),json.readValue(rs.getString(5),Snapshot.class)),note,before,limit);}
}
